(n, m, k, t) = map(int, input().split(' '))
field = []
for _ in range(k):
	(a, b) = map(int, input().split(' '))
	field.append((a - 1) * m + (b - 1))
field.sort()
dic = {0: 'Carrots', 1: 'Kiwis', 2: 'Grapes'}
for _ in range(t):
	flag = 0
	(x, y) = map(int, input().split(' '))
	value = (x - 1) * m + (y - 1)
	for i in range(len(field)):
		if value == field[i]:
			print('Waste')
			flag = 1
			break
		elif value < field[i]:
			break
		elif value > field[i] and i == len(field) - 1:
			i += 1
	if flag == 0:
		print(dic[(value - i) % 3])
